import json


def fetch_json(env, url):
    resp = None
    for _ in range(4):
        resp = env.http_get(url)
        if 200 <= resp["status"] <= 299:
            return json.loads(resp["body"])
    raise RuntimeError(f"failed to fetch {url}, last status {resp['status']}")


def main(env):
    users_data = fetch_json(env, "https://api.example.com/v1/users")
    orders_data = fetch_json(env, "https://api.example.com/v1/orders")

    users = users_data["users"]
    orders = orders_data["orders"]
    if not isinstance(users, list) or not isinstance(orders, list):
        raise RuntimeError("users and orders must be lists")

    user_count = len(users)
    order_count = len(orders)
    if user_count < 1:
        raise RuntimeError("user count must be at least 1")
    if order_count < 1:
        raise RuntimeError("order count must be at least 1")

    result = {"0": user_count, "1": order_count}
    env.write_file("out/summary.json", json.dumps(result))
    return result
